from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify the start and end indices of each group of nested parentheses
    groups = []
    start = 0
    stack = []

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append((start, i))

    # Step 3: Extract each group using the indices and store them in a list
    result = []
    for start, end in groups:
        result.append(paren_string[start:end+1])

    # Step 4: Check each group for balanced parentheses and discard any invalid groups
    valid_groups = []
    for group in result:
        stack = []
        is_valid = True
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    is_valid = False
                    break
                stack.pop()
        if is_valid and not stack:
            valid_groups.append(group)

    # Step 5: Return the list of valid groups as separate strings
    return valid_groups

